CREATE TABLE "PurchaseOrderReturn"("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "PurchaseOrder"("id") ON DELETE CASCADE,"requestedById" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL UNIQUE,"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'REQUESTED',"decisionReason" TEXT,"approvedById" TEXT,"carrier" TEXT,"trackingNumber" TEXT,"receivedAt" TIMESTAMP(3),"receiveKey" TEXT UNIQUE,"receiptHash" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "PurchaseOrderReturn_orderId_status_idx" ON "PurchaseOrderReturn"("orderId","status");
CREATE TABLE "PurchaseOrderReturnItem"("id" TEXT PRIMARY KEY,"returnId" TEXT NOT NULL REFERENCES "PurchaseOrderReturn"("id") ON DELETE CASCADE,"orderItemId" TEXT NOT NULL REFERENCES "PurchaseOrderItem"("id") ON DELETE CASCADE,"quantity" INTEGER NOT NULL,"receivedQuantity" INTEGER NOT NULL DEFAULT 0,"restockQuantity" INTEGER NOT NULL DEFAULT 0,UNIQUE("returnId","orderItemId"));
CREATE TABLE "PurchaseOrderRefund"("id" TEXT PRIMARY KEY,"orderId" TEXT NOT NULL REFERENCES "PurchaseOrder"("id") ON DELETE CASCADE,"paymentId" TEXT NOT NULL REFERENCES "PurchaseOrderPayment"("id") ON DELETE CASCADE,"returnId" TEXT REFERENCES "PurchaseOrderReturn"("id") ON DELETE SET NULL,"requestedById" TEXT NOT NULL,"approvedById" TEXT,"idempotencyKey" TEXT NOT NULL UNIQUE,"amountCents" INTEGER NOT NULL,"currency" TEXT NOT NULL,"reason" TEXT NOT NULL,"cancelOrder" BOOLEAN NOT NULL DEFAULT false,"status" TEXT NOT NULL DEFAULT 'REQUESTED',"decisionReason" TEXT,"providerReference" TEXT,"attempts" INTEGER NOT NULL DEFAULT 0,"lastError" TEXT,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "PurchaseOrderRefund_orderId_status_idx" ON "PurchaseOrderRefund"("orderId","status");
CREATE INDEX "PurchaseOrderRefund_status_availableAt_idx" ON "PurchaseOrderRefund"("status","availableAt");
